import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.Dnb1kVW5.js";const h=JSON.parse('{"title":"Privacy","description":"","frontmatter":{"title":"Privacy"},"headers":[],"relativePath":"docs/concepts/privacy.md","filePath":"docs/concepts/privacy.md","lastUpdated":1789172339000}'),s={name:"docs/concepts/privacy.md"};function n(c,e,d,i,l,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Orby is built local-first: a model running on your own machine can handle chat, categorization, and every analysis in the app, and none of your data has to leave your device unless you explicitly connect a cloud model.</p><h2 id="trusted-vs-untrusted-models" tabindex="-1">Trusted vs. untrusted models <a class="header-anchor" href="#trusted-vs-untrusted-models" aria-label="Permalink to &quot;Trusted vs. untrusted models&quot;">​</a></h2><p>In Settings, you can configure a <strong>trusted</strong> main model — the one that has access to your actual project data — separately from any <strong>untrusted supporting models</strong> used for other backend tasks, which are never given access to your data at all. Make sure if you send data to an untrusted model, that it is first redacted.</p><h2 id="redacting-documents-yourself" tabindex="-1">Redacting documents yourself <a class="header-anchor" href="#redacting-documents-yourself" aria-label="Permalink to &quot;Redacting documents yourself&quot;">​</a></h2><p>If you want to share or save a document (like a sample statement) without exposing personal information, use the <a href="/orby-releases/docs/tools/pii-redactor">PII Redactor</a> tool directly.</p>',6)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
